import React from 'react';
import { useNavigate } from 'react-router-dom';
import FranchiseList from './FranchiseList';
import { logout } from '../services/api';
import { Button, Container, Typography, Grid, Paper, Box } from '@mui/material';
import ExamCounts from './count';

const Dashboard = () => {
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      await logout(navigate);
      localStorage.removeItem('token');
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      <Paper elevation={4} sx={{ p: 4, mb: 4 }}>
        <Typography
          variant="h4"
          align="center"
          color="red"
          gutterBottom
          sx={{ mb: 6 }} // Increased margin below the header
        >
          WELCOME TO SUPERADMIN DASHBOARD
        </Typography>
        <Grid container spacing={4} sx={{ mb: 4 }}>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="primary"
              fullWidth
              sx={{ padding: '14px 24px', fontSize: '16px' }}
              onClick={() => navigate('/create-superadmin')}
            >
              Create User
            </Button>
          </Grid>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="secondary"
              fullWidth
              sx={{ padding: '14px 24px', fontSize: '16px' }}
              onClick={() => navigate('/create-franchise')}
            >
              Create Franchise
            </Button>
          </Grid>

          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="success"
              fullWidth
              sx={{
                padding: '16px 28px',
                fontSize: '18px',
                backgroundColor: '#4CAF50', // Green color
                '&:hover': {
                  backgroundColor: '#45a049', // Darker green on hover
                  boxShadow: '0px 4px 20px rgba(0, 0, 0, 0.2)', // Hover effect with shadow
                },
              }}
              onClick={() => navigate('/exam-data')} // This navigates to the exam data page
            >
              Manage Exam Data
            </Button>
          </Grid>

          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="error"
              fullWidth
              sx={{ padding: '14px 24px', fontSize: '16px' }}
              onClick={handleLogout}
            >
              Logout
            </Button>
          </Grid>
        </Grid>
      </Paper>

      <Paper elevation={3} sx={{ p: 3 }}>
        <Typography variant="h5" align="center" gutterBottom sx={{ mb: 3 }}>
          Exam Summary
        </Typography>
        <Box sx={{ display: 'flex', justifyContent: 'space-evenly', flexWrap: 'wrap' }}>
          <Box sx={{ minWidth: '150px', maxWidth: '200px', textAlign: 'center', mb: 2 }}>
            <Paper elevation={3} sx={{ padding: 2, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              <Typography variant="h6">Total Exams</Typography>
              <Typography variant="h4" color="primary">
                150
              </Typography>
            </Paper>
          </Box>

          <Box sx={{ minWidth: '150px', maxWidth: '200px', textAlign: 'center', mb: 2 }}>
            <Paper elevation={3} sx={{ padding: 2, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              <Typography variant="h6">Pending Exams</Typography>
              <Typography variant="h4" color="warning">
                12
              </Typography>
            </Paper>
          </Box>

          <Box sx={{ minWidth: '150px', maxWidth: '200px', textAlign: 'center', mb: 2 }}>
            <Paper elevation={3} sx={{ padding: 2, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              <Typography variant="h6">Completed Exams</Typography>
              <Typography variant="h4" color="success">
                98
              </Typography>
            </Paper>
          </Box>
        </Box>
        <ExamCounts /> {/* This component will now show up under the count boxes */}
        <FranchiseList />
      </Paper>
    </Container>
  );
};

export default Dashboard;
